INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8025, 'ប្រៀបធៀប \(-1\dfrac{10}{12}\) និង \(-1\dfrac{9}{13}\)៖', NULL, '["\\(1\\dfrac{10}{12} < -1\\dfrac{9}{13}\\)", "\\(-1\\dfrac{10}{12} > -1\\dfrac{9}{13}\\)", "\\(-1\\dfrac{10}{12} = -1\\dfrac{9}{13}\\)", "\\(-1\\dfrac{10}{12} < -1\\dfrac{9}{13}\\)"]', 3, NULL, 3, 'mcq', '\(1\dfrac{10}{12} = \dfrac{11}{6} \approx 1.83 > \dfrac{22}{13} \approx 1.69\) ដូច្នេះចំនួនអវិជ្ជមានមានតម្លៃតូចជាង។', 'ចំនួនសនិទាន', 'hard', 1, '8', 'ចំនួនសនិទាន', NULL, 0);
