INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8027, 'គណនា \(-\dfrac{5}{24} - \dfrac{7}{30}\)៖', NULL, '["\\(-\\dfrac{53}{54}\\)", "\\(\\dfrac{1}{40}\\)", "\\(-\\dfrac{2}{9}\\)", "\\(-\\dfrac{53}{120}\\)"]', 3, NULL, 3, 'mcq', '\(\text{LCM}(24, 30) = 120\) ៖ \(\dfrac{-25-28}{120} = -\dfrac{53}{120}\)។', 'ចំនួនសនិទាន', 'hard', 1, '8', 'ចំនួនសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8028, 'គណនា \(0.75 \times \dfrac{13}{125}\)៖', NULL, '["\\(\\dfrac{13}{166}\\)", "\\(\\dfrac{39}{50}\\)", "\\(\\dfrac{39}{500}\\)", "\\(\\dfrac{13}{500}\\)"]', 2, NULL, 3, 'mcq', '\(\dfrac{3}{4} \times \dfrac{13}{125} = \dfrac{39}{500}\)។', 'ចំនួនសនិទាន', 'hard', 1, '8', 'ចំនួនសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8029, 'គណនា \(\dfrac{28}{27} \div \dfrac{-4}{51}\)៖', NULL, '["\\(-\\dfrac{112}{51}\\)", "\\(\\dfrac{119}{9}\\)", "\\(-\\dfrac{119}{9}\\)", "\\(-\\dfrac{17}{9}\\)"]', 2, NULL, 3, 'mcq', '\(\dfrac{28}{27} \times \dfrac{51}{-4} = -\dfrac{7 \times 17}{9} = -\dfrac{119}{9}\)។', 'ចំនួនសនិទាន', 'hard', 1, '8', 'ចំនួនសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8030, 'គណនា \(\left(\dfrac{1}{2} + \dfrac{1}{3}\right) \div \left(\dfrac{5}{8} - \dfrac{1}{4}\right)\)៖', NULL, '["\\(4\\dfrac{4}{9}\\)", "\\(\\dfrac{9}{20}\\)", "\\(2\\dfrac{2}{9}\\)", "\\(\\dfrac{5}{18}\\)"]', 2, NULL, 3, 'mcq', '\(\dfrac{5}{6} \div \dfrac{3}{8} = \dfrac{5}{6} \times \dfrac{8}{3} = \dfrac{20}{9}\)។', 'ចំនួនសនិទាន', 'hard', 1, '8', 'ចំនួនសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8031, 'រៀបចំនួន \(\dfrac{1}{8}, -\dfrac{9}{7}, -1, 0.28, 1\dfrac{2}{5}\) ពីតូចទៅធំ៖', NULL, '["\\(-1 < -\\dfrac{9}{7} < \\dfrac{1}{8} < 0.28 < 1\\dfrac{2}{5}\\)", "\\(-\\dfrac{9}{7} < -1 < 0.28 < \\dfrac{1}{8} < 1\\dfrac{2}{5}\\)", "\\(-\\dfrac{9}{7} < \\dfrac{1}{8} < -1 < 0.28 < 1\\dfrac{2}{5}\\)", "\\(-\\dfrac{9}{7} < -1 < \\dfrac{1}{8} < 0.28 < 1\\dfrac{2}{5}\\)"]', 3, NULL, 3, 'mcq', '\(-1.29 < -1 < 0.125 < 0.28 < 1.4\)។', 'ចំនួនសនិទាន', 'hard', 1, '8', 'ចំនួនសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8032, 'ក្នុងសិក្ខាសាលាមួយ តន្ត្រីករមាន \(\dfrac{1}{4}\) សិល្បករ \(\dfrac{2}{5}\) អ្នករបាំ \(\dfrac{1}{10}\) និងអ្នកដែលនៅសល់ជាអ្នកនិពន្ធ។ អ្នកនិពន្ធតាងដោយប្រភាគ៖', NULL, '["\\(\\dfrac{3}{10}\\)", "\\(\\dfrac{3}{4}\\)", "\\(\\dfrac{1}{4}\\)", "\\(\\dfrac{1}{5}\\)"]', 2, NULL, 3, 'mcq', '\(\dfrac{1}{4} + \dfrac{2}{5} + \dfrac{1}{10} = \dfrac{3}{4}\) ; \(1 - \dfrac{3}{4} = \dfrac{1}{4}\)។', 'ចំនួនសនិទាន', 'pisa', 1, '8', 'ចំនួនសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8033, 'ប្រាក់ខែមួយខែចំណាយ \(\dfrac{1}{2}\) លើម្ហូប \(\dfrac{1}{20}\) លើសៀវភៅ \(\dfrac{1}{10}\) លើធ្វើដំណើរ និង \(\dfrac{1}{25}\) លើអនឡាញ។ ប្រាក់សន្សំតាងដោយប្រភាគ៖', NULL, '["\\(\\dfrac{1}{4}\\)", "\\(\\dfrac{69}{100}\\)", "\\(\\dfrac{31}{100}\\)", "\\(\\dfrac{1}{5}\\)"]', 2, NULL, 3, 'mcq', '\(\dfrac{50+5+10+4}{100} = \dfrac{69}{100}\) ; \(1 - \dfrac{69}{100} = \dfrac{31}{100}\)។', 'ចំនួនសនិទាន', 'pisa', 1, '8', 'ចំនួនសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8034, 'ចតុកោណកែងមួយមានបរិមាត្រ \(16.38\ \text{cm}\) ហើយជ្រុងមួយ \(3.26\ \text{cm}\)។ ជ្រុងមួយទៀតមានប្រវែង៖', NULL, '["\\(8.19\\ \\text{cm}\\)", "\\(4.93\\ \\text{cm}\\)", "\\(13.12\\ \\text{cm}\\)", "\\(5.12\\ \\text{cm}\\)"]', 1, NULL, 3, 'mcq', 'កន្លះបរិមាត្រ \(8.19\) ; \(8.19 - 3.26 = 4.93\)។', 'ចំនួនសនិទាន', 'pisa', 1, '8', 'ចំនួនសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8035, 'ចតុកោណកែងមួយមានជ្រុង \(3.26\ \text{cm}\) និង \(4.93\ \text{cm}\)។ ផ្ទៃក្រឡា \(\mathcal{A}\) ស្មើ៖', NULL, '["\\(16.0718\\ \\text{cm}^2\\)", "\\(16.38\\ \\text{cm}^2\\)", "\\(8.19\\ \\text{cm}^2\\)", "\\(160.718\\ \\text{cm}^2\\)"]', 0, NULL, 3, 'mcq', '\(\mathcal{A} = 3.26 \times 4.93 = 16.0718\)។', 'ចំនួនសនិទាន', 'pisa', 1, '8', 'ចំនួនសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8036, 'រូបមន្តធ្វើនំមួយបាច់ប្រើម្សៅ \(2\dfrac{1}{4}\) កែវ។ ធ្វើបាន \(3\dfrac{1}{2}\) បាច់ ត្រូវប្រើម្សៅប៉ុន្មានកែវ?', NULL, '["\\(7\\dfrac{7}{8}\\)", "\\(5\\dfrac{3}{4}\\)", "\\(\\dfrac{9}{14}\\)", "\\(15\\dfrac{3}{4}\\)"]', 0, NULL, 3, 'mcq', '\(\dfrac{9}{4} \times \dfrac{7}{2} = \dfrac{63}{8} = 7\dfrac{7}{8}\)។', 'ចំនួនសនិទាន', 'pisa', 1, '8', 'ចំនួនសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8037, 'ក. សរសេរ \(28.45\) ជាប្រភាគសម្រួលរួច។ ខ. ប្រៀបធៀប \(0.54\) និង \(0.5398\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(28.45 = \dfrac{2\,845}{100} = \dfrac{569}{20} = 28\dfrac{9}{20}\) (3 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8038, 'ក្នុងចំនួន \(\dfrac{2}{5}, \dfrac{1}{2}, \dfrac{4}{9}\) រកចំនួនធំជាងគេ ហើយរៀបពីតូចទៅធំ។', NULL, '[]', 0, NULL, 5, 'writing', 'ភាគបែងរួមតូចបំផុតនៃ \(5, 2, 9\) គឺ \(90\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8039, 'ក. កំណត់ \(x\) ដើម្បីឱ្យ \(\dfrac{45}{x} = 7\dfrac{1}{2}\)។ ខ. កំណត់ \(x, y\) ដើម្បីឱ្យ \(\dfrac{-2}{x} = \dfrac{y}{5} = -0.2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(7\dfrac{1}{2} = \dfrac{15}{2}\) ; \(15x = 45 \times 2\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8040, 'ក. សរសេរ \(\dfrac{3}{16}\) និង \(\dfrac{7}{40}\) ជាចំនួនទសភាគ។ ខ. សរសេរ \(0.\overline{4}\) និង \(0.\overline{27}\) ជាប្រភាគ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{3}{16} = \dfrac{3 \times 625}{10\,000} = 0.1875\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8041, 'គណនា ក. \(-\dfrac{5}{24} - \dfrac{7}{30}\) ខ. \(\dfrac{1}{15} - \dfrac{27}{50}\) គ. \(-\dfrac{5}{6} - \left(-\dfrac{7}{3}\right)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\text{LCM}(24,30) = 120\) ; \(\dfrac{-25-28}{120} = -\dfrac{53}{120}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8042, 'បង្ហាញថា \(\dfrac{13}{4} + \dfrac{13}{9} = \dfrac{13}{4} \times \dfrac{13}{9}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'អង្គខាងឆ្វេង \(\dfrac{13 \times 9 + 13 \times 4}{4 \times 9} = \dfrac{13(9+4)}{36}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8043, 'គណនា ក. \(\left(\dfrac{1}{2} + \dfrac{1}{3}\right) \div \left(\dfrac{5}{8} - \dfrac{1}{4}\right)\) ខ. \(\dfrac{3\frac{2}{5} - \frac{25}{8}}{\frac{7}{12} + 5\frac{4}{9}}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{5}{6} \div \dfrac{3}{8} = \dfrac{5}{6} \times \dfrac{8}{3} = \dfrac{20}{9} = 2\dfrac{2}{9}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8044, 'រៀបចំនួន \(\dfrac{1}{8}, -\dfrac{9}{7}, -1, 0.28, 1\dfrac{2}{5}\) តាមលំដាប់ពីតូចទៅធំ ហើយពន្យល់។', NULL, '[]', 0, NULL, 5, 'writing', 'បំប្លែងជាទសភាគ \(\dfrac{1}{8} = 0.125\) ; \(-\dfrac{9}{7} \approx -1.29\) ; \(1\dfrac{2}{5} = 1.4\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8045, 'បើ \(\dfrac{a}{b} < \dfrac{c}{d}\) ចូរបង្ហាញថា \(\dfrac{a}{b} + \dfrac{e}{f} < \dfrac{c}{d} + \dfrac{e}{f}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាផលដក \(\left(\dfrac{c}{d} + \dfrac{e}{f}\right) - \left(\dfrac{a}{b} + \dfrac{e}{f}\right)\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8046, 'ប្រាក់ចំណូលមួយខែចំណាយ \(\dfrac{1}{2}\) លើម្ហូប \(\dfrac{1}{20}\) លើសៀវភៅ \(\dfrac{1}{10}\) លើធ្វើដំណើរ និង \(\dfrac{1}{25}\) លើអនឡាញ។ ក. រកប្រភាគចំណាយសរុប។ ខ. រកប្រភាគប្រាក់សន្សំ។ គ. បើចំណូល \(2\,000\,000\) ៛ សន្សំបានប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{50 + 5 + 10 + 4}{100} = \dfrac{69}{100}\) (ភាគបែងរួម \(100\)) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8047, 'ក្នុងសិក្ខាសាលាមួយ តន្ត្រីករមាន \(\dfrac{1}{4}\) សិល្បករ \(\dfrac{2}{5}\) អ្នករបាំ \(\dfrac{1}{10}\) ហើយនៅសល់ជាអ្នកនិពន្ធ។ ក. រកប្រភាគអ្នកនិពន្ធ។ ខ. បើមានអ្នកចូលរួមសរុប \(200\) នាក់ មានអ្នកនិពន្ធប៉ុន្មាននាក់?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{1}{4} + \dfrac{2}{5} + \dfrac{1}{10} = \dfrac{5 + 8 + 2}{20} = \dfrac{3}{4}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8048, 'ចតុកោណកែងមួយមានបរិមាត្រ \(16.38\ \text{cm}\)។ ក. រកកន្លះបរិមាត្រ។ ខ. បើជ្រុងមួយ \(3.26\ \text{cm}\) រកជ្រុងមួយទៀត។ គ. គណនាផ្ទៃក្រឡា \(\mathcal{A}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(16.38 \div 2 = 8.19\ \text{cm}\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8049, 'រូបមន្តធ្វើនំមួយបាច់ប្រើម្សៅ \(2\dfrac{1}{4}\) កែវ និងស្ករ \(\dfrac{3}{4}\) កែវ។ ក. ធ្វើ \(3\dfrac{1}{2}\) បាច់ ត្រូវប្រើម្សៅប៉ុន្មានកែវ? ខ. ត្រូវប្រើស្ករប៉ុន្មានកែវ? គ. ម្សៅច្រើនជាងស្ករប៉ុន្មានដង (ក្នុងមួយបាច់)?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{9}{4} \times \dfrac{7}{2} = \dfrac{63}{8} = 7\dfrac{7}{8}\) កែវ (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8050, 'រង្វាន់ \(3\,000\,000\) ៛ ចែកឱ្យអ្នកឈ្នះទី ១ បាន \(\dfrac{1}{3}\) ទី ២ បាន \(\dfrac{2}{5}\) ហើយនៅសល់ជារង្វាន់ទី ៣។ ក. រកប្រភាគរង្វាន់ទី ៣។ ខ. រករង្វាន់នីមួយៗជារៀល។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(1 - \dfrac{1}{3} - \dfrac{2}{5} = \dfrac{15 - 5 - 6}{15} = \dfrac{4}{15}\) (2 ពិន្ទុ)
